package com.crosscheck.service;
import com.crosscheck.model.Candidate;import org.springframework.stereotype.Service;import java.time.*;
@Service public class RiskEngineService{public void calculate(Candidate c){int gap=0;if(c.getRelievingDate()!=null&&c.getJoiningDate()!=null&&c.getJoiningDate().isAfter(c.getRelievingDate()))gap=(int)java.time.temporal.ChronoUnit.MONTHS.between(c.getRelievingDate(),c.getJoiningDate());c.setEmploymentGapMonths(Math.max(0,gap));int risk=0;if(c.isDuplicateEmail())risk+=20;if(c.isDuplicateMobile())risk+=15;if(c.isDuplicateResume())risk+=20;risk+=Math.min(c.getActiveOffers()*12,24);if(gap>3)risk+=15;if(c.getNoticePeriodDays()>60)risk+=10;if("PENDING".equals(c.getEducationStatus()))risk+=6;if("PENDING".equals(c.getIdentityStatus()))risk+=6;if("PENDING".equals(c.getOfferLetterStatus()))risk+=8;if("FAILED".equals(c.getOfferLetterStatus())||"MISMATCH".equals(c.getOfferLetterStatus()))risk+=25;if(c.getExperienceYears()>8&&c.getPreviousCompany()==null)risk+=8;risk=Math.min(100,risk);c.setRiskScore(risk);c.setRiskLevel(risk<=40?"LOW":risk<=70?"MEDIUM":"HIGH");int salaryFit=c.getCurrentSalary()>0?(int)Math.max(0,100-Math.abs(c.getExpectedSalary()-c.getCurrentSalary())/c.getCurrentSalary()*100):70;int join=(c.getCandidateInterest()+c.getInterviewFeedback()+c.getPreviousAcceptanceRate()+salaryFit+(100-Math.min(c.getNoticePeriodDays(),100)))/5-c.getActiveOffers()*8;c.setJoiningProbability(Math.max(5,Math.min(99,join)));if(risk<=40&&c.getJoiningProbability()>=70){c.setAiRecommendation("RECOMMENDED TO HIRE");c.setAiReason("Low hiring risk with strong joining intent and acceptable verification signals.");}else if(risk>=71){c.setAiRecommendation("HOLD / FURTHER REVIEW");c.setAiReason("High-risk indicators require additional document, background and reference verification.");}else{c.setAiRecommendation("PROCEED WITH CAUTION");c.setAiReason("Moderate risk detected. Complete pending checks before final offer release.");}}}
